  ('nike-court-vision-low', 'NIK', 'Nike Court Vision Low (Blanco / Negro)', 'CVL', 'LOW', 'Blanco / Negro', 'Inspiración de cancha de los 80 en un perfil bajo y limpio, con materiales que incluyen contenido reciclado.', 'Capellada sintética con perforaciones, swoosh en contraste y suela de caucho con círculo de pivote. Un básico blanco de precio accesible.', 'CLÁSICO', 459950, 0, '/assets/models/nike-court-vision-low.glb', true, '{"basePath":"/assets/products/nike-court-vision-low/","files":[],"aspect":"4/5","ready":false}'::jsonb, '{"upper":"Sintético con perforaciones","lining":"Textil","midsole":"Espuma ligera","outsole":"Caucho con círculo de pivote","closure":"Cordones planos","fit":"TRUE_TO_SIZE","weightGrams":420,"care":["Limpiar con paño húmedo","No usar lavadora"],"palette":{"upper":"#FFFFFF","accent":"#111111","sole":"#F1F1EF"},"hotspots":[{"id":"upper","label":"Sintético con perforaciones","position":[0.02,0.06,0.05],"normal":[0,0,1]},{"id":"midsole","label":"Espuma ligera","position":[-0.09,0.015,0.04],"normal":[0,0,1]},{"id":"outsole","label":"Caucho con círculo de pivote","position":[0,-0.01,0],"normal":[0,-1,0]}]}'::jsonb, ARRAY['clasico', 'basquet', 'urbano', 'blanco']::text[])
) AS v(slug, brand_code, name, model_code, silhouette, colorway, short_description, description, badge,
       price, discount, model_3d_url, model_3d_ready, images, specs, tags)
JOIN brands b ON b.tenant_id = '00000000-0000-4000-8000-000000000001' AND b.code = v.brand_code
ON CONFLICT (tenant_id, slug) DO UPDATE SET
  brand_id = EXCLUDED.brand_id,
  name = EXCLUDED.name,
  model_code = EXCLUDED.model_code,
  silhouette = EXCLUDED.silhouette,
  colorway = EXCLUDED.colorway,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
  badge = EXCLUDED.badge,
  original_price_cop = EXCLUDED.original_price_cop,
  discount_percent = EXCLUDED.discount_percent,
  model_3d_url = EXCLUDED.model_3d_url,
  model_3d_ready = EXCLUDED.model_3d_ready,
  image_placeholder_paths = EXCLUDED.image_placeholder_paths,
  material_specs = EXCLUDED.material_specs,
  style_tags = EXCLUDED.style_tags,
  is_active = true,
  updated_at = now();

-- ---------- Modelos retirados de la lista ----------
UPDATE products SET is_active = false, updated_at = now()
WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND slug IN ('adidas-forum-low', 'new-balance-574', 'nike-air-jordan-1-retro-high-og', 'adidas-campus-00s-gris-negro');

UPDATE product_variants v SET is_active = false, updated_at = now()
FROM products p
WHERE p.id = v.product_id AND p.tenant_id = v.tenant_id
  AND p.tenant_id = '00000000-0000-4000-8000-000000000001' AND p.slug IN ('adidas-forum-low', 'new-balance-574', 'nike-air-jordan-1-retro-high-og', 'adidas-campus-00s-gris-negro');

-- ---------- Variantes: tallas 36–44 con la regla de stock del proyecto ----------
INSERT INTO product_variants (tenant_id, product_id, sku, size_eu, stock)
SELECT p.tenant_id, p.id, 'KS-' || b.code || '-' || p.model_code || '-' || s.size, s.size,
       3 + abs(hashtext(p.slug || s.size::text)) % 10
FROM products p
JOIN brands b ON b.tenant_id = p.tenant_id AND b.id = p.brand_id
CROSS JOIN generate_series(36, 44) AS s(size)
WHERE p.tenant_id = '00000000-0000-4000-8000-000000000001' AND p.slug IN ('nike-air-force-1-low-07-blanco', 'adidas-superstar', 'nike-dunk-low-retro-panda', 'air-jordan-1-low', 'vans-old-skool', 'adidas-samba-og-blanco-negro', 'converse-chuck-taylor-all-star-clasico', 'adidas-stan-smith', 'new-balance-550', 'new-balance-530', 'adidas-campus-00s', 'puma-suede-xl', 'adidas-handball-spezial', 'air-jordan-4', 'nike-court-vision-low')
ON CONFLICT (product_id, size_eu) DO UPDATE SET
  sku = EXCLUDED.sku,
  is_active = true,
  updated_at = now();

-- ---------- Verificación (falla la transacción si algo no cuadra) ----------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND is_active;
  IF n <> 15 THEN RAISE EXCEPTION 'V002: se esperaban 15 productos activos, hay %', n; END IF;

  SELECT count(*) INTO n FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND is_active AND has_discount;
  IF n <> 4 THEN RAISE EXCEPTION 'V002: se esperaban 4 descuentos activos, hay %', n; END IF;
  IF EXISTS (SELECT 1 FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND is_active AND has_discount
             AND discount_percent NOT BETWEEN 10 AND 15) THEN
    RAISE EXCEPTION 'V002: descuento fuera de 10%%-15%%'; END IF;
  IF (SELECT count(*) FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND (slug, final_price_cop) IN (('nike-air-force-1-low-07-blanco', 526400), ('converse-chuck-taylor-all-star-clasico', 254900), ('new-balance-530', 466300), ('puma-suede-xl', 395900))) <> 4 THEN
    RAISE EXCEPTION 'V002: precios finales con descuento inesperados'; END IF;

  SELECT count(*) INTO n FROM product_variants v JOIN products p ON p.id = v.product_id
  WHERE p.tenant_id = '00000000-0000-4000-8000-000000000001' AND p.is_active AND v.is_active;
  IF n <> 135 THEN RAISE EXCEPTION 'V002: se esperaban 135 variantes activas (15 x 9), hay %', n; END IF;

  IF EXISTS (SELECT 1 FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND is_active
             AND (image_placeholder_paths->>'ready')::boolean
             AND jsonb_array_length(image_placeholder_paths->'files') = 0) THEN
    RAISE EXCEPTION 'V002: producto con ready=true sin archivos'; END IF;

  IF EXISTS (SELECT 1 FROM products WHERE tenant_id = '00000000-0000-4000-8000-000000000001' AND is_active
             AND model_3d_ready AND model_3d_url IS NULL) THEN
    RAISE EXCEPTION 'V002: modelo 3D listo sin URL'; END IF;
END $$;

COMMIT;
